      "() {\n    this.el = document.querySelector(\".showcase\");\n    this.missionMedia = ",
      "document.querySelector(\".mission__media\");\n    if (!this.el) return;\n    this.cr",
      "eateFilm();\n    this.renderUI();\n    this.loop();\n  }\n\n  createFilm() {\n    this",
      ".film = document.createElement(\"div\");\n    this.film.className = \"showcase-film\"",
      ";\n    this.film.innerHTML = `\n      <video class=\"showcase-film__video\" autoplay",
      " muted loop playsinline poster=\"https://res.cloudinary.com/dsdhxhhqh/image/uploa",
      "d/v1780405513/hero-engine_isebcf.png\">\n        <source src=\"https://assets.mixki",
      "t.co/videos/6853/6853-720.mp4\" type=\"video/mp4\" />\n      </video>\n      <div cla",
      "ss=\"showcase-film__overlay\"></div>\n    `;\n    document.body.appendChild(this.fil",
      "m);\n    this.filmOverlay = this.film.querySelector(\".showcase-film__overlay\");\n ",
      " }\n\n  renderUI() {\n    this.el.innerHTML = `\n      <div class=\"showcase__sticky\"",
      ">\n        <div class=\"showcase__ui\" aria-live=\"polite\">\n          <div class=\"sh",
      "owcase__panels\">\n            ${TABS.map((t, i) => `\n              <div class=\"sh",
      "owcase__panel${i === 0 ? \" is-active\" : \"\"}\" data-index=\"${i}\" aria-hidden=\"${i ",
      "!== 0}\">\n                <span class=\"showcase__panel-num\">${t.num}</span>\n     ",
      "           <h2 class=\"showcase__panel-title\">${t.title}</h2>\n                <p ",
      "class=\"showcase__panel-desc\">${t.desc}</p>\n              </div>`).join(\"\")}\n    ",
      "      </div>\n          <nav class=\"showcase__tabs-nav\" aria-label=\"Technology se",
      "ctions\">\n            ${TABS.map((t, i) => `\n              <div class=\"showcase__",
      "tab${i === 0 ? \" is-active\" : \"\"}\" data-index=\"${i}\" role=\"tab\" aria-selected=\"$",
      "{i === 0}\">\n                <span class=\"showcase__tab-bar\" aria-hidden=\"true\"><",
      "/span>\n                <span class=\"showcase__tab-name\">${t.label}</span>\n      ",
      "          <span class=\"showcase__tab-num\">${t.num}</span>\n              </div>`)",
      ".join(\"\")}\n          </nav>\n        </div>\n      </div>\n    `;\n    this.ui = thi",
      "s.el.querySelector(\".showcase__ui\");\n    this.panels = this.el.querySelectorAll(",
      "\".showcase__panel\");\n    this.tabs = this.el.querySelectorAll(\".showcase__tab\");",
      "\n  }\n\n  cardToRect(mr) { return { top: mr.top, left: mr.left, width: mr.width, h",
      "eight: mr.height, radius: 0 }; }\n\n  applyRect(r) {\n    this.film.style.top = `${",
      "r.top.toFixed(2)}px`;\n    this.film.style.left = `${r.left.toFixed(2)}px`;\n    t",
      "his.film.style.width = `${r.width.toFixed(2)}px`;\n    this.film.style.height = `",
      "${r.height.toFixed(2)}px`;\n    this.film.style.borderRadius = `${r.radius.toFixe",
